<script setup>
import { appConfig } from '../config/appConfig'
defineProps({ items: { type: Array, default: () => [] }, open: Boolean })
defineEmits(['close', 'remove', 'clear', 'detail'])
const money = (value) => new Intl.NumberFormat(appConfig.currency.locale, { style: 'currency', currency: 'ARS', maximumFractionDigits: 0 }).format(value)
const rows = [['Precio', (p) => money(p.priceArs)], ['Marca', (p) => p.brand], ['Presentación', (p) => p.size], ['Familia', (p) => p.family], ['Concentración', (p) => p.concentration], ['Duración', (p) => p.duration], ['Proyección', (p) => p.projection], ['Ocasión', (p) => p.occasion], ['Estación', (p) => p.season]]
</script>
<template><div v-if="open" class="fixed inset-0 z-50 overflow-y-auto bg-black/80 p-4 backdrop-blur-sm" @click.self="$emit('close')"><div class="mx-auto my-8 max-w-6xl rounded-3xl border border-white/10 bg-panel p-5 sm:p-8"><div class="flex items-center justify-between"><div><p class="text-xs uppercase tracking-widest text-gold-400">Comparador</p><h2 class="font-display text-4xl">Compará fragancias</h2></div><button class="h-10 w-10 rounded-full border border-white/10 text-xl" @click="$emit('close')">×</button></div><div class="mt-7 overflow-x-auto luxury-menu-scroll"><table class="w-full min-w-[700px] border-separate border-spacing-2"><thead><tr><th></th><th v-for="item in items" :key="item.id" class="w-1/3 rounded-2xl bg-black/30 p-4"><button @click="$emit('detail', item)"><img :src="item.image" :alt="item.name" class="mx-auto h-32 w-32 rounded-xl object-cover" /><span class="mt-3 block font-display text-xl">{{ item.name }}</span></button><button class="mt-2 text-xs text-red-300" @click="$emit('remove', item.id)">Quitar</button></th></tr></thead><tbody><tr v-for="([label, getter]) in rows" :key="label"><th class="p-3 text-left text-xs uppercase tracking-wider text-zinc-500">{{ label }}</th><td v-for="item in items" :key="item.id" class="rounded-xl bg-black/20 p-3 text-center text-sm">{{ getter(item) }}</td></tr></tbody></table></div></div></div></template>
